<template>
 <div class="ledger-page">
  <section class="card-compact"><h2>{{mine?'我的工资条':'工资条发布与签收'}}</h2><p>只发布齐全且审核通过的工资。签收表示核对本版本明细，实际到账另行核对。</p><div class="ledger-tools"><el-date-picker v-if="!mine" v-model="period" type="month" value-format="YYYY-MM" :clearable="false" @change="load"/><el-button @click="load">刷新</el-button></div><p v-if="error" role="alert" class="ledger-error">{{error}}</p></section>
  <section v-if="!mine" class="card-compact"><h3>待发布的已审核汇总</h3><el-table :data="candidates" v-loading="loading"><el-table-column prop="name" label="员工"/><el-table-column label="实发汇总"><template #default="{row}">{{yuan(row.totals.net_salary)}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{row.all_approved?'齐全且已审核':'数据未齐或审核未完成'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button :disabled="!row.all_approved" link type="primary" @click="ask('publish',row)">发布／更正</el-button></template></el-table-column></el-table></section>
  <section class="card-compact"><h3>{{mine?'已发布给本人的工资条':'发布版本及签收进度'}}</h3><el-table :data="items" v-loading="loading" empty-text="暂无已发布工资条"><el-table-column v-if="!mine" prop="name" label="员工"/><el-table-column prop="period" label="月份"/><el-table-column prop="revision" label="版本" width="80"/><el-table-column label="状态"><template #default="{row}">{{row.withdrawn_at?'已撤回':row.objection_at?'有异议':row.confirmed_at?'已署名确认':row.viewed_at?'已查看':'待领取'}}</template></el-table-column><el-table-column prop="confirmed_at" label="确认时间" min-width="180"/><el-table-column label="操作" min-width="220"><template #default="{row}"><el-button v-if="mine" link :disabled="!!row.withdrawn_at" @click="open(row.id)">查看与签收</el-button><template v-else><el-button link :disabled="!!row.withdrawn_at" @click="ask('remind',row)">企微个人提醒</el-button><el-button link :disabled="!!row.withdrawn_at" @click="ask('withdraw',row)">撤回</el-button><span v-if="row.objection">异议：{{row.objection}}</span></template></template></el-table-column></el-table></section>
  <section v-if="selected&&!selected.withdrawn_at" class="card-compact"><h3>{{selected.snapshot.name}} · {{selected.period}} · 第{{selected.revision}}版</h3><div class="ledger-details"><div>应发<strong>{{yuan(selected.snapshot.totals.gross_salary)}}</strong></div><div>代扣<strong>{{yuan(selected.snapshot.totals.deductions)}}</strong></div><div>实发<strong>{{yuan(selected.snapshot.totals.net_salary)}}</strong></div></div><el-table :data="selected.snapshot.contributions"><el-table-column prop="store_name" label="承担门店"/><el-table-column label="应发"><template #default="{row}">{{yuan(row.gross_salary)}}</template></el-table-column><el-table-column label="代扣"><template #default="{row}">{{yuan(row.deductions)}}</template></el-table-column><el-table-column label="实发"><template #default="{row}">{{yuan(row.net_salary)}}</template></el-table-column></el-table><details v-for="c in selected.snapshot.contributions" :key="c.sheet_id"><summary>{{c.store_name}} · 工资组成及扣项</summary><p v-for="[key,label] in PAYSLIP_FIELDS" :key="key">{{label}}：{{yuan(c[key])}}</p></details><p v-if="selected.receipt?.confirmed_at">已由 {{selected.receipt.confirmation_name}} 于 {{selected.receipt.confirmed_at}} 确认本版本。</p><p v-if="selected.receipt?.objection">已提交异议：{{selected.receipt.objection}}</p><div class="ledger-tools"><el-button type="primary" :disabled="!!selected.receipt?.confirmed_at" @click="ask('confirm',selected)">本人署名确认</el-button><el-button @click="ask('objection',selected)">提出异议</el-button></div></section>
  <section v-if="!mine&&deliveries.length" class="card-compact"><h3>提醒结果（与签收状态分开）</h3><p v-for="d in deliveries" :key="d.id">工资条 {{d.payslip_id}} · {{deliveryLabels[d.state]||d.state}} · {{d.detail}}</p></section>
  <NotificationDialog v-model="dialog" :title="titles[action]||'处理工资条'" :close-on-click-modal="false"><p v-if="action==='confirm'">请核对工资明细后填写本人档案姓名。此处确认不表示工资已实际到账，也不放弃提出异议的权利。</p><p v-if="action==='remind'">向该员工已绑定的企业微信账号发送个人提醒，仅包含月份和登录入口，不含工资金额。</p><template v-if="action==='confirm'"><el-input v-model="name" placeholder="填写本人档案姓名"/><el-checkbox v-model="accept">我已查看并确认本版本工资明细</el-checkbox></template><el-input v-else-if="action!=='remind'" v-model="reason" type="textarea" maxlength="500" :placeholder="action==='publish'?'首次发布可不填，更正或重新发布须填写原因':'填写原因或需要核对的问题'"/><p class="ledger-error" role="alert">{{dialogError}}</p><template #footer><el-button :disabled="busy" @click="dialog=false">取消</el-button><el-button :loading="busy" type="primary" @click="submit">{{action==='remind'?'确认发送提醒':'确认'}}</el-button></template></NotificationDialog>
  <NotificationDialog v-model="consentDialog" title="薪资个人信息单独同意" :close-on-click-modal="false"><p>为向本人提供工资条、核对和签收，将处理本人薪资明细、员工身份、查看时间、署名确认及异议记录。薪资属于敏感个人信息，泄露可能影响财产安全；仅本人及经授权人员按职责查看。拒绝后不加载工资条，其他功能仍可使用。</p><p class="ledger-error">{{dialogError}}</p><template #footer><el-button @click="consentDialog=false">暂不同意</el-button><el-button type="primary" :loading="busy" @click="agree">单独同意</el-button></template></NotificationDialog>
 </div>
</template>
<script setup>
import {computed,onActivated,onDeactivated,ref,watch} from 'vue'
import {businessLedgerApi as api} from '@/api'
import NotificationDialog from '@/components/NotificationDialog.vue'
import '@/styles/business-ledger.css'
import {PAYSLIP_FIELDS} from '../../../../shared/payslip-fields.mjs'
const props=defineProps({mode:{type:String,default:'manage'}})
const mine=computed(()=>props.mode==='mine'),period=ref(new Date().toISOString().slice(0,7)),items=ref([]),candidates=ref([]),deliveries=ref([]),selected=ref(null),loading=ref(false),error=ref(''),busy=ref(false),dialog=ref(false),action=ref(''),target=ref(null),reason=ref(''),name=ref(''),accept=ref(false),dialogError=ref('')
const titles={publish:'发布工资条版本',withdraw:'撤回工资条',remind:'发送个人提醒',confirm:'本人署名确认',objection:'提出工资条异议'},deliveryLabels={sent:'接口接受提醒',failed:'发送失败',sending:'正在发送',unknown:'结果待核实'},yuan=v=>'￥'+Number(v||0).toFixed(2)
let generation=0,detailGeneration=0
const consentDialog=ref(false),privacyVersion=ref('')
async function agree(){busy.value=true;try{await api.payslipConsent(privacyVersion.value);consentDialog.value=false;await load()}catch(e){dialogError.value=e.message}finally{busy.value=false}}
async function load(){const n=++generation;loading.value=true;error.value='';try{if(mine.value){const c=await api.context();privacyVersion.value=c.privacy_version;if(!c.employee_bound){items.value=[];error.value='账号尚未绑定员工档案，请联系管理员核验';return}if(!c.payslip_consent){items.value=[];consentDialog.value=true;return}const r=await api.mine();if(n===generation)items.value=r.items}else{const r=await Promise.all([api.candidates(period.value),api.published(period.value)]);if(n===generation){candidates.value=r[0].items;items.value=r[1].items;deliveries.value=r[1].deliveries}}}catch(e){if(n===generation)error.value=e.message}finally{if(n===generation)loading.value=false}}
async function open(id){const n=++detailGeneration;try{const r=await api.slip(id);if(n===detailGeneration){selected.value=r.item;if(r.item.withdrawn_at)error.value='此版本已撤回，请查看最新版本'}}catch(e){error.value=e.message}}
function ask(kind,row){action.value=kind;target.value=row;reason.value='';name.value='';accept.value=false;dialogError.value='';dialog.value=true}
async function submit(){if(busy.value)return;busy.value=true;dialogError.value='';try{const r=target.value;if(action.value==='publish')await api.publish({employee_id:r.employee_id,period:period.value,reason:reason.value});else if(action.value==='withdraw')await api.withdraw(r.id,{reason:reason.value});else if(action.value==='remind')await api.remind(r.id);else{await api.receipt(r.id,{action:action.value,content_hash:r.content_hash,note:reason.value,confirmation_name:name.value,accept:accept.value});await open(r.id)}dialog.value=false;await load()}catch(e){dialogError.value=e.message}finally{busy.value=false}}
watch(mine,()=>{selected.value=null;detailGeneration++;load()});onActivated(load)
onDeactivated(()=>{dialog.value=false;consentDialog.value=false;generation++;detailGeneration++})
</script>
